const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const reject = (reason, statusCode = 401) => [{ json: { valid: false, reason, statusCode } }];
const secret = $env.LENDLOOP_OUTBOUND_SECRET;
if (!secret) return reject('secret not configured');
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
if (!/^\d{1,12}$/.test(timestamp)) return reject('bad timestamp');
if (Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale timestamp');
if (!item.binary || !item.binary.data) return reject('missing raw body');
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = Buffer.from('v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + raw).digest('hex'));
const received = Buffer.from(signature);
if (expected.length !== received.length || !crypto.timingSafeEqual(expected, received)) return reject('bad signature');
let payload;
try { payload = JSON.parse(raw); } catch (e) { return reject('invalid json', 400); }
const eventId = payload && payload.eventId;
if (typeof eventId !== 'string' || !eventId || !payload.recipient || typeof payload.recipient.email !== 'string' || !payload.recipient.email.trim()) {
  return reject('invalid payload', 400);
}
return [{ json: { valid: true, eventId, payload } }];

const staticData = $getWorkflowStaticData('global');
const seen = staticData.processedEventIds || [];
const current = $input.first().json;
return [{ json: { ...current, duplicate: seen.includes(current.eventId) } }];

const { payload } = $input.first().json;
const loan = payload.loan || {};
const tool = (payload.tool && payload.tool.name) || 'a tool';
const name = (payload.recipient && payload.recipient.firstName) || 'there';
const dates = loan.startDate && loan.endDate ? ' (' + loan.startDate + ' to ' + loan.endDate + ')' : '';
const subjects = {
  requested: 'New request for ' + tool,
  approved: 'Your request for ' + tool + ' was approved',
  declined: 'Your request for ' + tool + ' was declined',
  returned: 'Thanks for returning ' + tool,
  cancelled: 'A request for ' + tool + ' was cancelled'
};
const lines = {
  requested: 'Someone asked to borrow ' + tool + dates + '.',
  approved: 'Good news: you can pick up ' + tool + dates + '.',
  declined: 'Your request for ' + tool + dates + ' was declined.',
  returned: tool + ' is marked as returned. Thank you!',
  cancelled: 'The request for ' + tool + dates + ' was cancelled.'
};
const status = loan.status;
return [{ json: {
  to: payload.recipient.email,
  subject: subjects[status] || 'Update on ' + tool,
  text: 'Hi ' + name + ',\n\n' + (lines[status] || 'The status of your loan changed to ' + status + '.') +
    '\n\nOpen it here: ' + (payload.link || '') + '\n\nLendLoop'
} }];

const staticData = $getWorkflowStaticData('global');
const seen = staticData.processedEventIds || [];
const eventId = $('Verify signature').first().json.eventId;
seen.push(eventId);
staticData.processedEventIds = seen.slice(-500);
return [{ json: { eventId, recorded: true } }];
